changeSet.sql:
ALTER TABLE ingestion_batch
  ADD CONSTRAINT chk_ingestion_batch_status
  CHECK (status IN ('running', 'succeeded', 'failed'));
ALTER TABLE management_catchments
  ADD CONSTRAINT chk_management_catchments_water_type
  CHECK (water_type IN ('surface', 'groundwater'));
ALTER TABLE waterbody_features
  ADD CONSTRAINT chk_waterbody_features_water_type
  CHECK (water_type IN ('surface', 'groundwater'));
ALTER TABLE assessment_point_waterbodies
  ADD CONSTRAINT chk_apw_validation_status
  CHECK (validation_status IN ('pending', 'valid', 'invalid'));

changeSet.rollback:
ALTER TABLE assessment_point_waterbodies DROP CONSTRAINT IF EXISTS chk_apw_validation_status;
ALTER TABLE waterbody_features DROP CONSTRAINT IF EXISTS chk_waterbody_features_water_type;
ALTER TABLE management_catchments DROP CONSTRAINT IF EXISTS chk_management_catchments_water_type;
ALTER TABLE ingestion_batch DROP CONSTRAINT IF EXISTS chk_ingestion_batch_status;
